<?php
require_once '../../config/config.php'; require_once '../../config/database.php'; require_once '../../includes/access.php';
access_require_roles(array('Admin','Teacher','Student')); access_require_feature($conn, 'reports'); $conn->set_charset('utf8mb4');
function student_reports_e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$student_id=(int)($_GET['student_id']??0);$stmt=$conn->prepare('SELECT s.student_name,s.admission_no,s.class_id,s.section_id,c.class_name,sec.section_name FROM students s JOIN classes c ON c.id=s.class_id JOIN sections sec ON sec.id=s.section_id WHERE s.id=? AND s.status=1');$stmt->bind_param('i',$student_id);$stmt->execute();$student=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$student){http_response_code(404);exit('Student not found.');}
if(access_is_student()&&$student_id!==access_student_id()){http_response_code(403);exit('You can only view your own report cards.');}
if(access_is_teacher()&&!access_teacher_can_class($conn,(int)$student['class_id'],(int)$student['section_id'])){http_response_code(403);exit('You can only view report cards for assigned classes.');}
$exams=array();$current_session_id=access_current_academic_session($conn);$q=$conn->prepare('SELECT id,exam_name FROM exams WHERE status=1 AND (?=0 OR session_id=?) ORDER BY id DESC');$q->bind_param('ii',$current_session_id,$current_session_id);$q->execute();$exam_result=$q->get_result();while($x=$exam_result->fetch_assoc())$exams[]=$x;$q->close();
?>
<?php include '../../includes/header.php';include '../../includes/navbar.php';include '../../includes/sidebar.php';?>
<div class="content-wrapper"><section class="content-header"><div class="container-fluid"><h1>Report Cards</h1></div></section><section class="content"><div class="container-fluid"><div class="alert alert-info"><strong><?=student_reports_e($student['student_name'])?></strong> — <?=student_reports_e($student['class_name'].' / '.$student['section_name'])?> — Admission No: <?=student_reports_e($student['admission_no'])?></div><div class="card"><div class="card-header bg-primary text-white">Available Report Cards</div><div class="card-body"><div class="list-group"><?php foreach($exams as $exam):?><a target="_blank" class="list-group-item list-group-item-action" href="report_card.php?student_id=<?=$student_id?>&class_id=<?=$student['class_id']?>&section_id=<?=$student['section_id']?>&exam_id=<?=$exam['id']?>"><i class="fas fa-file-alt mr-2"></i><?=student_reports_e($exam['exam_name'])?> <span class="float-right">View Report Card <i class="fas fa-external-link-alt"></i></span></a><?php endforeach;?></div></div></div></div></section></div><?php include '../../includes/footer.php';?>
